import ReactDOM from 'react-dom';
import React, { useState, useEffect } from 'react';
import { Tabs, Tab } from 'react-bootstrap';
import InventoryTable from './InventoryTable';
import StageView from './StageView';
import InvoiceView from './InvoiceView';
import { supabase } from './supabaseClient';
import 'bootstrap/dist/css/bootstrap.min.css';

const APPVERSION = '2.0.4';

export default function App() {
  const [inventory, setInventory] = useState([]);
  const [stagedItems, setStagedItems] = useState([]);
  const [discount, setDiscount] = useState(10);
  const [activeTab, setActiveTab] = useState('inventory');

  useEffect(() => {
    console.log("Active tab changed to:", activeTab);
  }, [activeTab]);

  // Fetch inventory on mount: includes selected flags
  useEffect(() => {
    async function fetchInventory() {
      const { data, error } = await supabase
        .from("inventory")
        .select("*")
        .order("id");

      if (error) {
        console.error("Error fetching inventory", error);
        return;
      }

      const mapped = (data || []).map(item => ({
        id: item.id,
        section: item.section,
        product: item.product,
        unitPrice: item.unit_price,
        count: item.count,
        description: item.description,
        selected: String(item.selected).toLowerCase() === "true",
        askCount: item.ask_count || 0,      // <- map ask_count from DB
      }));

      // Restore staged items from localStorage if available
      const savedStage = localStorage.getItem("stagedItems");
      let savedStaged = [];
      if (savedStage) {
        try {
          savedStaged = JSON.parse(savedStage);
        } catch {
          savedStaged = [];
        }
      }

      // If saved stagedItems exist, sync inventory with it
      let syncedInventory = mapped;
      if (savedStaged.length > 0) {
        syncedInventory = mapped.map(item => {
          const found = savedStaged.find(s => s.id === item.id);
          return { ...item, selected: Boolean(found) };
        });
        setStagedItems(savedStaged);
      } else {
        // Else fallback to inventory selected items
        setStagedItems(mapped.filter(item => item.selected));
      }

      setInventory(syncedInventory);

      console.log("Fetched inventory:", mapped);
      console.log("Initial staged items:", mapped.filter(item => item.selected));
    }

    fetchInventory();
  }, []);

  // Update inventory item in DB and local state
  async function updateItem(id, updates) {
    const dbUpdates = {};
    if ("section" in updates) dbUpdates.section = updates.section;
    if ("product" in updates) dbUpdates.product = updates.product;
    if ("unitPrice" in updates) dbUpdates.unit_price = updates.unitPrice;
    if ("count" in updates) dbUpdates.count = updates.count;
    if ("description" in updates) dbUpdates.description = updates.description;
    if ("selected" in updates) dbUpdates.selected = updates.selected;
    if ("askCount" in updates) dbUpdates.ask_count = updates.askCount;  // <- write askCount to ask_count

    const { error } = await supabase.from("inventory").update(dbUpdates).eq("id", id);

    if (error) {
      console.error("Update item error:", error);
      return;
    }

    setInventory(items => {
      const updatedItems = items.map(item =>
        item.id === id ? { ...item, ...updates } : item
      );

      if ("selected" in updates) {
        if (updates.selected) {
          const newItem = updatedItems.find(item => item.id === id);
          if (newItem) setStagedItems(prev => [...prev, newItem]);
        } else {
          setStagedItems(prev => prev.filter(item => item.id !== id));
        }
      }

      return updatedItems;
    });
  }

  // Insert new inventory item
  async function insertItem(initialData) {
    const dbInsert = {
      section: initialData.section,
      product: initialData.product,
      unit_price: initialData.unitPrice,
      count: initialData.count,
      description: initialData.description,
      selected: initialData.selected,
      ask_count: initialData.askCount ?? 0,   // ensure ask_count has a value
    };
    const { data, error } = await supabase.from("inventory").insert([dbInsert]).select();

    if (error) {
      console.error("Insert item error:", error);
      return null;
    }

    return {
      id: data[0].id,
      section: data[0].section,
      product: data[0].product,
      unitPrice: data[0].unit_price,
      count: data[0].count,
      description: data[0].description,
      selected: data[0].selected,
      askCount: data[0].ask_count || 0,
    };
  }

  // Generate stage button handler
  const generateStage = React.useCallback(async () => {
    try {
      for (const item of inventory) {
        const { error } = await supabase
          .from("inventory")
          .update({ selected: item.selected })
          .eq("id", item.id);
        if (error) {
          console.error("DB update error:", error);
          return;
        }
      }

      const selected = inventory.filter(i => i.selected);

      // Reset askCount when generating a new stage (DB optional)
      setStagedItems(selected.map(i => ({ ...i, askCount: 0 })));

      if (ReactDOM && ReactDOM.flushSync) {
        ReactDOM.flushSync(() =>
          setStagedItems(selected.map(i => ({ ...i, askCount: 0 })))
        );
        ReactDOM.flushSync(() => setActiveTab('stage'));
      } else {
        setTimeout(() => setActiveTab('stage'), 50);
      }
    } catch (error) {
      console.error(error);
    }
  }, [inventory, setStagedItems, setActiveTab]);

  // Reset all selections and staged items
  function resetSelected() {
    const cleared = inventory.map(item => ({ ...item, selected: false }));
    setInventory(cleared);
    setStagedItems([]);
  }

  return (
    <div className="container my-4">
      <div className="mb-3 text-muted" style={{ fontSize: '0.9rem', fontWeight: 'bold' }}>
        App Version v{APPVERSION}
      </div>

      <h1 className="mb-4">Inventory Manager Web App</h1>

      <Tabs
        activeKey={activeTab}
        onSelect={key => key && setActiveTab(key)}
        variant="pills"
        fill
        justify
        mountOnEnter
        unmountOnExit
      >
        <Tab eventKey="inventory" title="Inventory">
          <div className="my-3 d-flex flex-wrap gap-2 justify-content-start">
            <button className="btn btn-primary" onClick={async () => await generateStage()}>
              Generate Stage
            </button>
            <button className="btn btn-info" onClick={resetSelected}>
              Reset Selected Items
            </button>
          </div>
          <InventoryTable
            inventoryItems={inventory}
            setInventoryItems={setInventory}
            updateItem={updateItem}
            insertItem={insertItem}
            showAskCount={false}
          />
        </Tab>

        <Tab eventKey="stage" title="Stage">
          <StageView
            stagedItems={stagedItems}
            setStagedItems={setStagedItems}
            inventoryItems={inventory}
            updateItem={updateItem}
            insertItem={insertItem}
          />
        </Tab>

        <Tab eventKey="invoice" title="Invoice">
          <InvoiceView
            stagedItems={stagedItems}
            discount={discount}
            inventoryItems={inventory}
          />
        </Tab>
      </Tabs>
    </div>
  );
}
