import React, { useState, useEffect } from "react";

export default function InventoryTable({
  inventoryItems,
  setInventoryItems,
  updateItem,
  insertItem,
  showAskCount = false,
}) {
  const [editing, setEditing] = useState({ idx: null, field: null, value: "" });
  const [openSections, setOpenSections] = useState({});
  const [addingNewSection, setAddingNewSection] = useState(null);
  const [newProductData, setNewProductData] = useState({
    product: "",
    unitPrice: "",
    count: "",
  });
  const [activeAddSection, setActiveAddSection] = useState(null);

  const safeItems = Array.isArray(inventoryItems) ? inventoryItems : [];

  useEffect(() => {
    const sections = Array.from(new Set(safeItems.map(item => item.section)));
    const initialOpenState = {};
    sections.forEach(section => {
      if (!(section in openSections)) {
        initialOpenState[section] = false;
      } else {
        initialOpenState[section] = openSections[section];
      }
    });
    setOpenSections(prev => ({ ...prev, ...initialOpenState }));
  }, [safeItems]);

  const groupedBySection = safeItems.reduce((acc, item) => {
    if (!acc[item.section]) acc[item.section] = [];
    acc[item.section].push(item);
    return acc;
  }, {});

  function toggleSection(section) {
    setOpenSections(prev => ({
      ...prev,
      [section]: !prev[section],
    }));
  }

  function onSectionHeaderClick(section) {
    setActiveAddSection(section);
  }

  function openAddSection() {
    if (activeAddSection) {
      setAddingNewSection(activeAddSection);
      setNewProductData({ product: "", unitPrice: "", count: "" });
      const el = document.getElementById(`section-header-${activeAddSection}`);
      if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }

  async function confirmAddItem(section) {
    if (!newProductData.product || !newProductData.unitPrice) return;
    const newItem = {
      section,
      product: newProductData.product,
      unitPrice: parseFloat(newProductData.unitPrice).toFixed(2),
      count: parseInt(newProductData.count, 10) || 0,
      selected: false,
      askCount: 0,
    };
    if (insertItem) {
      const dbRecord = await insertItem(newItem);
      if (dbRecord) {
        const newItems = [...safeItems, dbRecord];
        const updatedItems = [];
        const sections = Array.from(new Set(newItems.map(item => item.section)));
        sections.forEach(sec => {
          const itemsInSec = newItems.filter(i => i.section === sec);
          itemsInSec.sort((a, b) => a.product.toLowerCase().localeCompare(b.product.toLowerCase()));
          updatedItems.push(...itemsInSec);
        });
        setInventoryItems(updatedItems);
        setAddingNewSection(null);
        setNewProductData({ product: "", unitPrice: "", count: "" });
      }
    }
  }

  function cancelAdd() {
    setAddingNewSection(null);
    setNewProductData({ product: "", unitPrice: "", count: "" });
  }

  function beginEdit(idx, field, value) {
    setEditing({ idx, field, value });
  }

  function handleEditChange(e) {
    setEditing(cur => ({ ...cur, value: e.target.value }));
  }

  async function handleEditCommit() {
    if (editing.idx === null || !editing.field) return;
    const newItems = [...safeItems];
    let val = editing.value;
    if (editing.field === "unitPrice" && val !== "") {
      val = Number(val).toFixed(2);
    }
    if (editing.field === "count" && val !== "") {
      val = parseInt(val, 10) || 0;
    }
    newItems[editing.idx] = { ...newItems[editing.idx], [editing.field]: val };
    setInventoryItems(newItems);

    if (updateItem) {
      const id = newItems[editing.idx]?.id;
      if (id) await updateItem(id, { [editing.field]: val });
    }
    setEditing({ idx: null, field: null, value: "" });
  }

  function handleKeyDown(e) {
    if (e.key === "Enter") handleEditCommit();
    if (e.key === "Escape") setEditing({ idx: null, field: null, value: "" });
  }

  function handleBlur() {
    handleEditCommit();
  }

  function formatPrice(price) {
    const num = parseFloat(price);
    if (isNaN(num)) return "$0.00";
    return "$" + num.toFixed(2);
  }

  return (
    <div style={{ position: "relative" }}>
      <div className="table-responsive" style={{ paddingTop: 10, paddingBottom: 120 }}>
        <div className="fw-bold mb-2">Total items: {safeItems.length}</div>
        {Object.entries(groupedBySection).map(([section, items]) => {
          const isOpen = openSections[section] || false;
          return (
            <div key={section} style={{ marginBottom: 10, border: "1px solid #ccc", borderRadius: 4 }}>
              <div
                id={`section-header-${section}`}
                onClick={() => {
                  toggleSection(section);
                  onSectionHeaderClick(section);
                }}
                style={{
                  background: activeAddSection === section ? "#a0bfff" : "#bababa",
                  padding: "8px 16px",
                  cursor: "pointer",
                  fontWeight: "bold",
                  userSelect: "none",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
                title="Tap to expand/collapse and select section to add product"
              >
                <span>{isOpen ? "▼" : "►"} {section}</span>
              </div>

              {addingNewSection === section && (
                <div style={{ padding: "8px 20px", background: "#e8f0fe" }}>
                  <input
                    type="text"
                    placeholder="Product Name"
                    value={newProductData.product}
                    onChange={e => setNewProductData(prev => ({ ...prev, product: e.target.value }))}
                    style={{ width: "40%", marginRight: 10 }}
                  />
                  <input
                    type="number"
                    placeholder="Price"
                    step="0.01"
                    value={newProductData.unitPrice}
                    onChange={e => setNewProductData(prev => ({ ...prev, unitPrice: e.target.value }))}
                    style={{ width: "25%", marginRight: 10 }}
                  />
                  <input
                    type="number"
                    placeholder="Count"
                    value={newProductData.count}
                    onChange={e => setNewProductData(prev => ({ ...prev, count: e.target.value }))}
                    style={{ width: "15%", marginRight: 10 }}
                  />
                  <button className="btn btn-success btn-sm me-2" onClick={() => confirmAddItem(section)}>
                    Confirm
                  </button>
                  <button className="btn btn-secondary btn-sm" onClick={cancelAdd}>
                    Cancel
                  </button>
                </div>
              )}

              {isOpen && (
                <table
                  className="table table-bordered table-striped text-center align-middle"
                  style={{ marginBottom: 0, width: "100%", fontWeight: 700 }}
                >
                  <thead>
                    <tr>
                      <th style={{ width: "10%" }}>Select</th>
                      <th style={{ width: "40%" }}>Product</th>
                      <th style={{ width: "15%" }}>Price</th>
                      <th style={{ width: "15%" }}>Qty</th>
                      {showAskCount && <th style={{ width: "10%" }}>Ask Count</th>}
                    </tr>
                  </thead>
                  <tbody>
                    {items.map((item) => {
                      const globalIdx = safeItems.findIndex(i => i.id === item.id);
                      return (
                        <tr key={item.id}>
                          <td>
                            <input
                              type="checkbox"
                              checked={!!item.selected}
                              onClick={e => e.stopPropagation()}
                              onMouseDown={e => e.stopPropagation()}
                              style={{ pointerEvents: "auto" }}
                              onChange={async e => {
                                const newSelected = e.target.checked;
                                const newItems = [...safeItems];
                                newItems[globalIdx] = { ...newItems[globalIdx], selected: newSelected };
                                setInventoryItems(newItems);
                                if (updateItem) await updateItem(item.id, { selected: newSelected });
                              }}
                            />
                          </td>
                          <td
                            onClick={e => { e.stopPropagation(); beginEdit(globalIdx, "product", item.product); }}
                            style={{ cursor: "pointer" }}
                            title={item.product}
                          >
                            {editing.idx === globalIdx && editing.field === "product" ? (
                              <input
                                autoFocus
                                type="text"
                                className="form-control form-control-sm"
                                value={editing.value}
                                onChange={handleEditChange}
                                onBlur={handleBlur}
                                onKeyDown={handleKeyDown}
                                style={{ fontWeight: 700, border: "2px solid #000" }}
                                onClick={e => e.stopPropagation()}
                                onMouseDown={e => e.stopPropagation()}
                              />
                            ) : (
                              item.product
                            )}
                          </td>
                          <td
                            onClick={e => { e.stopPropagation(); beginEdit(globalIdx, "unitPrice", item.unitPrice); }}
                            style={{ cursor: "pointer" }}
                          >
                            {editing.idx === globalIdx && editing.field === "unitPrice" ? (
                              <input
                                autoFocus
                                type="number"
                                inputMode="decimal"
                                step="0.01"
                                className="form-control form-control-sm text-center"
                                value={editing.value}
                                onChange={handleEditChange}
                                onBlur={handleBlur}
                                onKeyDown={handleKeyDown}
                                style={{ fontWeight: 700, border: "2px solid #000" }}
                                onClick={e => e.stopPropagation()}
                                onMouseDown={e => e.stopPropagation()}
                              />
                            ) : (
                              formatPrice(item.unitPrice)
                            )}
                          </td>
                          <td
                            onClick={e => { e.stopPropagation(); beginEdit(globalIdx, "count", item.count); }}
                            style={{ cursor: "pointer" }}
                          >
                            {editing.idx === globalIdx && editing.field === "count" ? (
                              <input
                                autoFocus
                                type="number"
                                inputMode="numeric"
                                className="form-control form-control-sm text-center"
                                value={editing.value}
                                onChange={handleEditChange}
                                onBlur={handleBlur}
                                onKeyDown={handleKeyDown}
                                style={{ fontWeight: 700, border: "2px solid #000" }}
                                onClick={e => e.stopPropagation()}
                                onMouseDown={e => e.stopPropagation()}
                              />
                            ) : (
                              item.count || ""
                            )}
                          </td>
                          {showAskCount && (
                            <td
                              onClick={e => { e.stopPropagation(); beginEdit(globalIdx, "askCount", item.askCount); }}
                              style={{ cursor: "pointer" }}
                            >
                              {editing.idx === globalIdx && editing.field === "askCount" ? (
                                <input
                                  autoFocus
                                  type="number"
                                  inputMode="numeric"
                                  className="form-control form-control-sm text-center"
                                  value={editing.value}
                                  onChange={handleEditChange}
                                  onBlur={handleBlur}
                                  onKeyDown={handleKeyDown}
                                  style={{ fontWeight: 700, border: "2px solid #000" }}
                                  onClick={e => e.stopPropagation()}
                                  onMouseDown={e => e.stopPropagation()}
                                />
                              ) : (
                                item.askCount || ""
                              )}
                            </td>
                          )}
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              )}
            </div>
          );
        })}
      </div>

      <button
        className="btn btn-success d-flex align-items-center justify-content-center"
        style={{
          position: "fixed",
          right: 16,
          bottom: 20,
          zIndex: 1000,
          width: 56,
          height: 56,
          borderRadius: "50%",
          fontSize: "28px",
          boxShadow: "0 4px 8px rgba(0,0,0,0.2)",
          userSelect: "none",
        }}
        disabled={!activeAddSection}
        title={activeAddSection ? `Add product to "${activeAddSection}"` : "Tap a section header to select it first"}
        onClick={openAddSection}
      >
        +
      </button>
    </div>
  );
}
